async function employeesFor(u:any){const ids=await visibleIDs(u),filter=ids===null?{}:{id:`in.(${ids.join(",")})`};return(await db(qp("employees",{select:"id,first_name,last_name,staff_number",status:"neq.inactive",order:"last_name.asc",limit:"500",...filter}))).data||[]}
